import { Initializer } from '@adobe-commerce/elsie/lib';
import { CompanyDropinConfig } from '../../types/api/initialize.types';

export const initialize = new Initializer<CompanyDropinConfig>({
  init: async (config) => {
    const defaultConfig = {};

    initialize.config.setConfig({ ...defaultConfig, ...config });
  },

  listeners: () => [],
});

export const config = initialize.config;
