import { fetchGraphQl } from '../fetch-graphql';
import { handleNetworkError } from '../../lib/network-error';
import { handleFetchError } from '../../lib/fetch-error';
import { Company } from '@/company-management/types';
import { transformCompanyHierarchyWithCompanies } from '@/company-management/data/transforms';
import { CompanyHierarchyResponse } from '@/company-management/types/api/getCompanyHierarchy.types';
import { GET_COMPANY_HIERARCHY } from './graphql/getCompanyHierarchy.graphql';

/**
 * Retrieves the company hierarchy with parent-child relationships
 *
 * @returns Promise resolving to array of Company objects representing the company hierarchy
 * @throws {Error} When network errors or GraphQL errors occur
 */
export async function getCompanyHierarchy(): Promise<Company[]> {
  return await fetchGraphQl<CompanyHierarchyResponse>(GET_COMPANY_HIERARCHY, {
    method: 'GET',
    cache: 'no-cache',
  })
    .then((res) => {
      if (res.errors?.length) return handleFetchError(res.errors);
      
      const hierarchyArray = res.data.customer.company_hierarchy;
      const companiesItems = res.data.customer.companies.items;

      // Use new transformer that handles both hierarchy and companies.items
      return transformCompanyHierarchyWithCompanies(
        hierarchyArray,
        companiesItems
      );
    })
    .catch(handleNetworkError);
}
