import { fetchGraphQl } from '../fetch-graphql';
import { handleNetworkError } from '../../lib/network-error';
import { handleFetchError } from '../../lib/fetch-error';
import { Company } from '@/company-management/types';
import { transformCompanyHierarchy } from '@/company-management/data/transforms';
import {
  AssignChildCompanyInput,
  AssignChildCompanyResponse,
} from '@/company-management/types/api/assignChildCompany.types';
import { ASSIGN_CHILD_COMPANY } from './graphql/assignChildCompany.graphql';

/**
 * Assign a child company to a parent company within the company relation hierarchy
 * 
 * @param parentCompanyId - The unique ID of the parent company
 * @param childCompanyId - The unique ID of the child company
 * @returns Promise resolving to array of Company objects representing the updated hierarchy
 * @throws {Error} When network errors or GraphQL errors occur
 */
export async function assignChildCompany(
  parentCompanyId: string,
  childCompanyId: string
): Promise<Company[]> {
  const input: AssignChildCompanyInput = {
    parent_company_id: parentCompanyId,
    child_company_id: childCompanyId,
  };

  return await fetchGraphQl<AssignChildCompanyResponse>(ASSIGN_CHILD_COMPANY, {
    variables: { input },
  })
    .then((res) => {
      if (res.errors?.length) return handleFetchError(res.errors);
      const hierarchy = res.data.assignChildCompany.company_hierarchy;

      // Use transformer to convert GraphQL response to model
      return transformCompanyHierarchy(hierarchy);
    })
    .catch(handleNetworkError);
}
