import { COMPANY_HIERARCHY_ITEM_FRAGMENT } from '../../graphql/CompanyHierarchyFragment.graphql';

export const UNASSIGN_CHILD_COMPANY = /* GraphQL */ `
  mutation unassignChildCompany($input: UnassignChildCompanyInput!) {
    unassignChildCompany(input: $input) {
      company_hierarchy {
        parent {
          ...COMPANY_HIERARCHY_ITEM_FRAGMENT
        }
        children {
          ...COMPANY_HIERARCHY_ITEM_FRAGMENT
        }
      }
    }
  }
  ${COMPANY_HIERARCHY_ITEM_FRAGMENT}
`;
