import { CompanyHierarchyItemResponse } from '@/company-management/types/api/getCompanyHierarchy.types';
import { Company } from '@/company-management/types';

/**
 * Transform company hierarchy item from GraphQL response to Company model
 */
export function transformCompanyHierarchyItem(
  item: CompanyHierarchyItemResponse,
  parentItem?: CompanyHierarchyItemResponse | null
): Company {
  return {
    id: item.id,
    name: item.name,
    is_admin: item.is_admin,
    parent_company: parentItem
      ? {
          id: parentItem.id,
          name: parentItem.name,
        }
      : null,
    child_companies: [],
  };
}

/**
 * Transform company hierarchy from GraphQL response to Company models
 * Converts the parent/children structure to a flat array with proper relationships
 */
export function transformCompanyHierarchy(
  hierarchy: {
    parent: CompanyHierarchyItemResponse | null;
    children: CompanyHierarchyItemResponse[];
  }
): Company[] {
  const companies: Company[] = [];

  // If there's a parent company, add it as root
  if (hierarchy.parent) {
    const parentCompany = transformCompanyHierarchyItem(hierarchy.parent);
    
    // Add children to parent company
    parentCompany.child_companies = hierarchy.children.map((child) =>
      transformCompanyHierarchyItem(child, hierarchy.parent)
    );
    
    companies.push(parentCompany);
  } else {
    // No parent means all children are root-level companies
    companies.push(
      ...hierarchy.children.map((child) => transformCompanyHierarchyItem(child))
    );
  }

  return companies;
}

/**
 * Transform company hierarchy with fallback to companies.items
 * This handles the case where hierarchy is empty but user has admin access to multiple companies
 * 
 * Logic:
 * 1. Process all hierarchy items (parent + children)
 * 2. Find companies.items that are NOT in hierarchy
 * 3. Add those companies as root-level
 */
export function transformCompanyHierarchyWithCompanies(
  hierarchyArray: Array<{
    parent: CompanyHierarchyItemResponse | null;
    children: CompanyHierarchyItemResponse[];
  }>,
  companiesItems: Array<{
    id: string;
    name: string;
    status: string;
    is_admin: boolean;
  }>
): Company[] {
  const companies: Company[] = [];
  const processedIds = new Set<string>();

  // Process all hierarchy items
  hierarchyArray.forEach((hierarchy) => {
    const hierarchyCompanies = transformCompanyHierarchy(hierarchy);
    
    // Track all IDs from hierarchy
    hierarchyCompanies.forEach((company) => {
      processedIds.add(company.id);
      
      // Also track child company IDs
      company.child_companies?.forEach((child) => {
        processedIds.add(child.id);
      });
      
      companies.push(company);
    });
  });

  // Add companies from items that are NOT in hierarchy (as root-level)
  companiesItems.forEach((item) => {
    if (!processedIds.has(item.id)) {
      companies.push({
        id: item.id,
        name: item.name,
        is_admin: item.is_admin,
        parent_company: null,
        child_companies: [],
      });
    }
  });

  return companies;
}
