import { fetchGraphQl } from '../fetch-graphql';
import { handleNetworkError } from '../../lib/network-error';
import { handleFetchError } from '../../lib/fetch-error';
import { Company } from '@/company-management/types';
import { transformCompanyHierarchy } from '@/company-management/data/transforms';
import {
  UnassignChildCompanyInput,
  UnassignChildCompanyResponse,
} from '@/company-management/types/api/unassignChildCompany.types';
import { UNASSIGN_CHILD_COMPANY } from './graphql/unassignChildCompany.graphql';

/**
 * Unassign a child company from its parent company within the company relation hierarchy
 * 
 * @param childCompanyId - The unique ID of the child company to unassign
 * @returns Promise resolving to array of Company objects representing the updated hierarchy
 * @throws {Error} When network errors or GraphQL errors occur
 */
export async function unassignChildCompany(
  childCompanyId: string
): Promise<Company[]> {
  const input: UnassignChildCompanyInput = {
    child_company_id: childCompanyId,
  };

  return await fetchGraphQl<UnassignChildCompanyResponse>(UNASSIGN_CHILD_COMPANY, {
    variables: { input },
  })
    .then((res) => {
      if (res.errors?.length) return handleFetchError(res.errors);
      const hierarchy = res.data.unassignChildCompany.company_hierarchy;

      // Use transformer to convert GraphQL response to model
      return transformCompanyHierarchy(hierarchy);
    })
    .catch(handleNetworkError);
}
